package de.yxnnick9.studio;

import javax.imageio.ImageIO;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.util.List;

/** Original built-in End Crystal styles, generated by recoloring the vanilla texture (no third-party assets). */
final class BuiltIn {
    private BuiltIn() {
    }

    /** mode: 0 = recolor, 1 = invisible (glass + core transparent), 2 = see-through (glass transparent). */
    record Style(String id, String label, float hue, float satMul, float valMul, int mode) {}

    static final List<Style> CRYSTAL = List.of(
            new Style("aqua", "Aqua", 0.50f, 1.0f, 1.0f, 0),
            new Style("blueberry", "Blueberry", 0.63f, 1.0f, 0.95f, 0),
            new Style("lavender", "Lavender", 0.74f, 0.55f, 1.1f, 0),
            new Style("marlow", "Marlow", 0.90f, 1.0f, 1.0f, 0),
            new Style("lime", "Lime", 0.30f, 1.0f, 1.0f, 0),
            new Style("gold", "Gold", 0.12f, 1.0f, 1.05f, 0),
            new Style("ruby", "Ruby", 0.99f, 1.0f, 0.95f, 0),
            new Style("snow", "Snow", 0.58f, 0.12f, 1.15f, 0),
            new Style("seethrough", "See-Through", 0f, 1f, 1f, 2),
            new Style("invisible", "Invisible", 0f, 1f, 1f, 1)
    );

    static Style byId(String id) {
        for (Style s : CRYSTAL) if (s.id().equals(id)) return s;
        return null;
    }

    /** Vanilla 64x32 end crystal texture: glass at (0,0,32x16), core at (32,0,32x16), base below. */
    static byte[] crystal(byte[] vanillaPng, Style st) {
        try {
            BufferedImage img = ImageIO.read(new ByteArrayInputStream(vanillaPng));
            if (img == null || img.getWidth() != img.getHeight() * 2) return null;
            int w = img.getWidth(), h = img.getHeight();
            BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
            for (int y = 0; y < h; y++) {
                for (int x = 0; x < w; x++) {
                    int argb = img.getRGB(x, y);
                    int a = argb >>> 24;
                    boolean top = y < h / 2;
                    boolean glass = top && x < w / 2, core = top && x >= w / 2;
                    if (a == 0 || (!glass && !core)) {
                        out.setRGB(x, y, argb);
                        continue;
                    }
                    if (st.mode() == 1 || (st.mode() == 2 && glass)) {
                        out.setRGB(x, y, 0);
                        continue;
                    }
                    if (st.mode() == 2) {
                        out.setRGB(x, y, argb);
                        continue;
                    }
                    float[] hsb = Color.RGBtoHSB((argb >> 16) & 255, (argb >> 8) & 255, argb & 255, null);
                    int rgb;
                    if (glass) {
                        int tint = Color.HSBtoRGB(st.hue(), Math.min(1f, 0.55f * st.satMul()), 1f);
                        float t = 0.55f;
                        int r = (int) (((argb >> 16) & 255) * (1 - t) + ((tint >> 16) & 255) * t);
                        int g = (int) (((argb >> 8) & 255) * (1 - t) + ((tint >> 8) & 255) * t);
                        int b = (int) ((argb & 255) * (1 - t) + (tint & 255) * t);
                        rgb = (r << 16) | (g << 8) | b;
                    } else if (hsb[1] > 0.08f) {
                        rgb = Color.HSBtoRGB(st.hue(), Math.min(1f, hsb[1] * st.satMul()), Math.min(1f, hsb[2] * st.valMul())) & 0xFFFFFF;
                    } else {
                        rgb = argb & 0xFFFFFF;
                    }
                    out.setRGB(x, y, (a << 24) | rgb);
                }
            }
            ByteArrayOutputStream bo = new ByteArrayOutputStream();
            ImageIO.write(out, "png", bo);
            return bo.toByteArray();
        } catch (Throwable t) {
            return null;
        }
    }
}
